@charset 'UTF-8';

#moreChannelsModal {
    .modal-content {
        min-height: 600px;
        max-height: calc(50vh - 240px);
    }

    .modal-dialog {
        margin-top: calc(45vh - 240px) !important;
    }

    .filter-row--full {
        position: relative;
        margin: 0 32px;

        .input-clear {
            top: 16px;
