            .more-modal__actions {
                button {
                    display: none;
                    min-width: 54px;
                    height: 32px;
                    font-size: 12px;
                    font-weight: 600;
                }
            }
        }

        .more-modal__row:hover,
        .more-modal__row:focus {
            background-color: rgba(var(--center-channel-color-rgb), 0.08);
            cursor: pointer;

            .more-modal__actions {
                .primaryButton,
                .outlineButton {
                    display: inline-block;
                }
            }
        }

        .form-group {
            padding: 0 32px;
            margin-bottom: 0;
        }

        ::-webkit-scrollbar {
            width: 4px;
        }

        ::-webkit-scrollbar-track {
            background: none;
        }
    }

    .modal-header {
        .GenericModal__header {
            display: flex;
            width: 95%;
            align-items: center;
            justify-content: space-between;
            padding-right: 4px;
        }

        .close {
            top: 22px;
        }
    }

    .outlineButton {
        border: 1px solid var(--button-bg);
        background: none;
        border-radius: 4px;
        color: var(--button-bg);
        font-size: 12px;
        font-weight: 600;
        line-height: 16px;
    }

    .outlineButton:hover {
        background-color: rgba(var(--button-bg-rgb), 0.08);
    }

    .filter-controls {
        padding: 0;

        button {
            min-width: 72px;
            margin: 8px 32px;
        }
    }
}

#moreChannelsList {
    .primary-message {
        margin-top: 8px;
        color: var(--center-channel-color);
        line-height: 28px;
    }

    .secondary-message {
        margin-bottom: 30px;
    }

    .primaryButton {
        background-color: var(--button-bg);
        border-radius: 4px;
        color: var(--button-color);
        font-size: 14px;
        font-weight: 600;
    }

    #createNewChannelButton {
        padding: 10px 20px;
    }
}

